UPDATE schedules
   SET taken_at = CASE WHEN #{isTaken} = 1 THEN SYSDATE ELSE NULL END
 WHERE schedule_id = #{scheduleId}

UPDATE schedules
   SET scheduled_at = TO_DATE(TO_CHAR(scheduled_at, 'YYYY-MM-DD') || ' ' || #{newTime}, 'YYYY-MM-DD HH24:MI')
 WHERE schedule_id = #{scheduleId}
